<?php
declare(strict_types=1);
define('CWP_BOOT',true);define('CWP_CODE_ROOT',__DIR__.'/../../site');require CWP_CODE_ROOT.'/includes/security/input.php';require CWP_CODE_ROOT.'/includes/layout/tickets.php';
$checks=[];$_POST=[];$_SERVER['REQUEST_METHOD']='GET';
function tf_ok(string $name,bool $pass):void {global $checks;$checks[]=['name'=>$name,'passed'=>$pass];if(!$pass)throw new RuntimeException($name);}
function tf_deny(string $name,callable $work):void {try{$work();}catch(InvalidArgumentException|LogicException){tf_ok($name,true);return;}tf_ok($name,false);}
function csrf_field():string {return '<input name="csrf" value="synthetic-form-token">';}
function support_csrf_field():string {return '<input name="csrf" value="synthetic-support-token">';}
function admin_url(string $view,array $params=[]):string {return '/existing/admin/index.php?'.http_build_query(['view'=>$view]+$params);}
function studio_url(array $params=[]):string {return '/existing/portal/index.php?'.http_build_query($params);}
function tf_html(callable $render):string {ob_start();try{$render();return ob_get_contents();}finally{ob_end_clean();}}
function tf_id(int $id):string {return str_pad(dechex($id),32,'0',STR_PAD_LEFT);}
try{
    tf_ok('Multiline input normalizes browser CRLF and preserves UTF-8',support_tickets_form_text(['body'=>"Café\r\nSecond\rThird"],'body',100,true)==="Café\nSecond\nThird");
    foreach(['',"bad\0text","bad\xff",str_repeat('a',181),"Two\nlines"] as $i=>$body)tf_deny('Invalid subject case '.$i.' is refused',fn()=>support_tickets_form_text(['subject'=>$body],'subject',180));
    tf_deny('Array body is refused',fn()=>support_tickets_form_text(['body'=>['forged']],'body',100,true));tf_ok('Optional missing search is empty',support_tickets_form_text([],'search',180,false,true)==='');
    foreach(['0'=>0,'1'=>1,'513'=>513] as $value=>$expected)tf_ok('Canonical revision '.$value.' parses exactly',support_tickets_form_number(['n'=>(string)$value],'n',513)===$expected);
    foreach(['','00','01','-1','+1','1e2','1.0',' 1','514','99999999999999999999',1,[]] as $i=>$value)tf_deny('Invalid revision form '.$i.' is refused',fn()=>support_tickets_form_number(['n'=>$value],'n',513));
    foreach(['',str_repeat('A',32),tf_id(1).' ',[tf_id(1)],str_repeat('a',33)] as $i=>$value)tf_deny('Malformed request identity '.$i.' is refused',fn()=>support_tickets_form_id(['id'=>$value],'id'));
    tf_ok('Intent preserves exact record request and revision',support_tickets_form_intent(['ticket_id'=>tf_id(1),'request_id'=>tf_id(2),'revision'=>'0'])===['ticket_id'=>tf_id(1),'request_id'=>tf_id(2),'revision'=>0]);
    foreach([[],['confirm'=>true],['confirm'=>'yes'],['confirm'=>['1']]] as $i=>$value)tf_deny('Missing explicit confirmation '.$i.' is refused',fn()=>support_tickets_form_confirm($value));support_tickets_form_confirm(['confirm'=>'1']);tf_ok('Exact status confirmation is accepted',true);
    tf_ok('Related references are in strict canonical kind order',support_tickets_form_links(['related_project'=>'3','related_invoice'=>'2','related_subscription'=>tf_id(4)])===[['kind'=>'invoice','id'=>'2'],['kind'=>'project','id'=>'3'],['kind'=>'subscription','id'=>tf_id(4)]]);
    tf_deny('Invalid numeric related reference is refused',fn()=>support_tickets_form_links(['related_project'=>'01']));tf_deny('Array related reference is refused',fn()=>support_tickets_form_links(['related_invoice'=>[]]));
    $values=support_tickets_form_values(['subject'=>str_repeat('é',100),'body'=>'</textarea><script>unsafe</script>','ticket_id'=>str_repeat('a',33),'current_password'=>'secret','csrf'=>'secret','confirm'=>'1']);
    tf_ok('Redisplay retains oversized UTF-8 text and invalid original identities without silently repairing them',$values['subject']===str_repeat('é',100)&&$values['ticket_id']===str_repeat('a',33));tf_ok('Passwords CSRF and status confirmation are excluded from redisplay',!isset($values['current_password'],$values['csrf'],$values['confirm']));
    $html=tf_html(fn()=>support_tickets_create_fields($values,[]));tf_ok('Creation redisplay escapes literal user markup',str_contains($html,'&lt;/textarea&gt;&lt;script&gt;unsafe&lt;/script&gt;')&&!str_contains($html,'<script>'));
    $fresh=support_tickets_ui_intent(tf_id(1),4,'tickets_reply');tf_ok('Fresh form has a new valid request and exact current revision',preg_match('/\A[a-f0-9]{32}\z/',$fresh['request_id'])===1&&$fresh['ticket_id']===tf_id(1)&&$fresh['revision']===4);
    $_SERVER['REQUEST_METHOD']='POST';$_POST=['action'=>'tickets_reply','ticket_id'=>tf_id(1),'request_id'=>tf_id(2),'revision'=>'1','body'=>'Unsaved <reply>'];$old=support_tickets_ui_intent(tf_id(1),6,'tickets_reply');tf_ok('Failed form keeps original request and stale revision',$old['request_id']===tf_id(2)&&$old['revision']==='1');tf_ok('Other action obtains current revision instead of borrowing stale intent',support_tickets_ui_intent(tf_id(1),6,'tickets_note')['revision']===6);
    $html=tf_html(fn()=>support_tickets_controls(tf_id(1),6,'open',true,false,true,[['id'=>3,'name'=>'Operator <three>']]));tf_ok('Staff sees public reply distinctly from private note',str_contains($html,'tickets_reply')&&str_contains($html,'tickets_note')&&str_contains($html,'visible only to staff'));tf_ok('Failed staff reply retains escaped draft and original identity',str_contains($html,'Unsaved &lt;reply&gt;')&&str_contains($html,'value="'.tf_id(2).'"')&&str_contains($html,'name="revision" value="1"'));tf_ok('Staff assignment escapes current option label',str_contains($html,'Operator &lt;three&gt;')&&!str_contains($html,'Operator <three>'));tf_ok('Status confirmation is never prechecked',!str_contains($html,' checked'));
    $html=tf_html(fn()=>support_tickets_controls(tf_id(1),7,'closed',true,false,true));tf_ok('Closed conversation preserves failed unsaved reply in disabled form',str_contains($html,'Unsaved &lt;reply&gt;')&&str_contains($html,' disabled')&&!str_contains($html,'tickets_note'));
    $_SERVER['REQUEST_METHOD']='GET';$_POST=[];$html=tf_html(fn()=>support_tickets_controls(tf_id(1),2,'open',false,false,true));tf_ok('Client controls exclude private note assignment and owner password',str_contains($html,'client_tickets_reply')&&!str_contains($html,'tickets_note')&&!str_contains($html,'tickets_assign')&&!str_contains($html,'current_password'));tf_ok('Client open status offers only closure',str_contains($html,'value="closed"')&&!str_contains($html,'value="pending"')&&!str_contains($html,'value="resolved"'));
    $html=tf_html(fn()=>support_tickets_controls(tf_id(1),2,'resolved',false,false,true));tf_ok('Resolved client can reopen or close',str_contains($html,'value="open"')&&str_contains($html,'value="closed"'));
    $html=tf_html(fn()=>support_tickets_controls(tf_id(1),2,'open',false,true,true));tf_ok('Support reply uses its bound CSRF and has no client status action',str_contains($html,'synthetic-support-token')&&!str_contains($html,'client_tickets_status'));tf_ok('Read-only support has no reply composer',tf_html(fn()=>support_tickets_controls(tf_id(1),2,'open',false,true,false))==='');tf_ok('Closed client has no mutation controls',tf_html(fn()=>support_tickets_controls(tf_id(1),2,'closed',false,false,true))==='');
    $doc=SupportTicketDocument::create(tf_id(1),1,'staff:2',100,'Ticket <title>',tf_id(2),'Opening <message>',[])->append(tf_id(3),'note','staff:2',101,['body'=>'PRIVATE only'])->append(tf_id(4),'assign','staff:2',101,['staff_id'=>3]);
    $public=$doc->forClient(1)['events'];$html=tf_html(fn()=>support_tickets_history_view(support_tickets_history_page($public,[]),fn($p)=>studio_url(['history'=>$p])));tf_ok('Client history contains escaped public opening without private note or assignment',str_contains($html,'Opening &lt;message&gt;')&&!str_contains($html,'PRIVATE')&&!str_contains($html,'Private assignment'));tf_deny('Client cannot focus a hidden private note',fn()=>support_tickets_history_page($public,['focus'=>tf_id(3)]));
    $staff=support_tickets_staff_events($doc);$html=tf_html(fn()=>support_tickets_history_view(support_tickets_history_page($staff,[]),fn($p)=>admin_url('ticket',['history'=>$p])));tf_ok('Staff history labels private notes and assignments',str_contains($html,'Private staff note')&&str_contains($html,'Private assignment')&&str_contains($html,'PRIVATE only'));tf_ok('Staff opening uses revision zero and actual creation time',$staff[0]['sequence']===0&&$staff[0]['at']===100);
    for($i=0;$i<65;$i++)$doc=$doc->append(tf_id(100+$i),'reply','client:1',102,['body'=>'Same-second reply '.$i]);$events=$doc->forClient(1)['events'];$last=support_tickets_history_page($events,[]);tf_ok('Long conversation defaults to bounded latest history page',$last['page']===2&&$last['last']===2&&count($last['events'])===6);$first=support_tickets_history_page($events,['history'=>'0']);tf_ok('Earlier history page contains only its displayed public sequence',count($first['events'])===30&&$first['events'][29]['sequence']===30);$focus=support_tickets_history_page($events,['focus'=>tf_id(130)]);tf_ok('Exact notification focus resolves the correct page even for same-second updates',$focus['page']===1&&in_array(tf_id(130),array_column($focus['events'],'id'),true));
    tf_deny('Unavailable history page is refused',fn()=>support_tickets_history_page($events,['history'=>'3']));tf_deny('Unknown focus is refused',fn()=>support_tickets_history_page($events,['focus'=>tf_id(999)]));tf_deny('Array history page is refused',fn()=>support_tickets_history_page($events,['history'=>[]]));
    $html=tf_html(fn()=>support_tickets_read_form(tf_id(1),30,false));tf_ok('Explicit read form retains only the displayed public cursor',str_contains($html,'name="revision" value="30"')&&str_contains($html,'client_tickets_read')&&!str_contains($html,'request_id'));
    $html=tf_html(fn()=>support_tickets_related_view([['kind'=>'invoice','id'=>'3','title'=>'Invoice <three>','job_id'=>7]],true));tf_ok('Staff invoice context uses exact existing project invoice anchor',str_contains($html,'view=studio-job&amp;id=7#invoice-3')&&str_contains($html,'Invoice &lt;three&gt;')&&!str_contains($html,'invoice-payments'));
}catch(Throwable $e){$checks[]=['name'=>'Unexpected failure: '.$e->getMessage(),'passed'=>false];}
$passed=!array_filter($checks,fn($c)=>!$c['passed']);echo json_encode(['passed'=>$passed,'scope'=>'Pure ticket form parsing, escaped controls and bounded public/staff history; no HTTP or current authority acceptance','checks'=>$checks],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($passed?0:1);
